with unpacked as (select id, plan, effective_from, currency, tier_limits, tier_prices, discounts, element_at(tier_prices, 1) as entry_price, zip_with(tier_prices, discounts, (p, d) -> round(p * (1 - d), 2)) as net_prices from price_tiers) select id, effective_from, entry_price, max(entry_price) over w_hist as last4_max_entry_price, min(entry_price) over w_hist as last4_min_entry_price, avg(entry_price) over w_hist as last4_avg_entry_price from unpacked window w_hist as (partition by currency order by entry_price, id rows between 3 preceding and current row)
